export class JobQueue {
  private running = 0;
  private pending: (() => Promise<void>)[] = [];
  private idleWaiters: (() => void)[] = [];
  private concurrency: number;
  private retries: number;

  constructor(concurrency: number, retries = 3) {
    if (!(concurrency >= 1)) throw new RangeError("concurrency must be >= 1");
    this.concurrency = concurrency;
    this.retries = retries;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        for (let attempt = 0; ; attempt++) {
          try {
            return resolve(await job());
          } catch (err) {
            if (attempt >= this.retries) return reject(err);
          }
        }
      });
      this.drain();
    });
  }

  /** Resolves once nothing is running or queued. */
  onIdle(): Promise<void> {
    if (this.running === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private drain(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      this.running++;
      void this.pending.shift()!().then(() => {
        this.running--;
        this.drain();
        if (this.running === 0) this.idleWaiters.splice(0).forEach((resolve) => resolve());
      });
    }
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { JobQueue } from "./queue.ts";

const tick = () => new Promise((r) => setTimeout(r, 5));

test("respects concurrency limit and onIdle waits for everything", async () => {
  const q = new JobQueue(2);
  let active = 0, peak = 0, done = 0;
  for (let i = 0; i < 6; i++) {
    void q.add(async () => {
      peak = Math.max(peak, ++active);
      await tick();
      active--;
      done++;
    });
  }
  await q.onIdle();
  assert.equal(peak, 2);
  assert.equal(done, 6);
});

test("retries up to three times, then rejects", async () => {
  const q = new JobQueue(1);
  let flaky = 0, dead = 0;
  const ok = q.add(async () => {
    if (++flaky < 4) throw new Error("flaky");
    return "ok";
  });
  const failed = q.add(async () => {
    dead++;
    throw new Error("dead");
  });
  assert.equal(await ok, "ok");
  await assert.rejects(failed, /dead/);
  assert.equal(flaky, 4);
  assert.equal(dead, 4);
  await q.onIdle();
});

